-- ===== t_announcement (15)：10 条改写真实正文 + 5 条新增 =====
INSERT INTO t_announcement(f_announcement_id,f_title,f_body,f_severity,f_sender_admin_id,f_sender_name,f_audience_type,f_pinned,f_scheduled,f_scheduled_time,f_sent_time,f_status,f_create_time) VALUES
(1,'FlamingoIM v4.2 客户端发布说明',
'各位伙伴：

FlamingoIM v4.2 PC 客户端将于本周五（5 月 22 日）22:00 起在 Windows 端逐步推送，预计 48 小时内完成全量灰度。

本次更新主要包含：
1. 重写联系人面板：新版组织架构支持任意级部门的折叠展开与面包屑导航，最深支持 8 级嵌套；
2. 消息加密链路升级：v2 协议默认启用 AES-GCM，旧版仍可读，但发送将统一走新管线；
3. 文件传输性能：单文件分片大小由 256KB 提到 1MB，弱网场景下断点续传提速约 40%；
4. 修复 23 个已知问题，详见随附 release notes。

如遇异常，请通过“帮助 → 反馈问题”上传日志；若需要回退到 v4.1，可在登录界面长按版本号 5 秒进入回退入口。

—— 平台运营组',
0,1,'平台运营',0,1,0,NULL,'2026-04-25 15:52:59',1,'2026-04-13 12:46:00'),
(2,'5月24日数据库维护通知',
'各位伙伴：

接 DBA 团队通知，将于 5 月 24 日（周日）凌晨 02:00 - 04:00 对主集群进行例行版本升级（MariaDB 10.6 → 10.11）。

影响范围：
- 维护窗口内消息收发、文件传输、登录会话可能出现 30 秒以内的间歇性中断；
- 已建立的长连接会自动重连，无需手动操作；
- 历史消息查询、组织架构修改等管理后台操作请尽量避开维护窗口。

回退预案：DBA 团队保留 4.5 小时的回退窗口；若升级后 1 小时内出现严重故障，将自动回滚到当前版本，全程对业务无感。

值班联系人：DBA 张工（13800000001）/ SRE 李工（13800000002），出现任何异常请第一时间拨打。',
1,1,'平台运营',1,0,0,NULL,'2026-04-30 13:22:58',1,'2026-04-12 17:21:54'),
(3,'安全公告：谨防钓鱼链接',
'最近收到多起内部员工反馈，有外部账号冒充“系统通知”服务号发送伪造的密码重置链接，已有少量员工误点，请大家务必提高警惕。

识别要点：
1. 官方系统通知服务号头像为铃铛图标，服务号名称右侧带有平台认证标识；
2. 任何要求输入“当前密码 + 新密码”的页面，域名必须以 mingyuan-tech.com 结尾，其它一律为钓鱼站点；
3. 真正的安全通知不会要求你点击短链接（t.cn、bit.ly 等），都是完整域名直链。

如果你已经在可疑页面输入过密码，请立即按以下顺序处置：
- 登录管理后台 → 个人中心 → 修改登录密码；
- 把可疑会话截图发送给“IT 支持”服务号；
- 半小时内观察账号是否有异地登录记录。

任何疑问可拨打 IT 支持热线 021-6800-0000 转 9，24 小时有人值守。',
2,1,'平台运营',0,0,0,NULL,'2026-04-22 08:00:50',1,'2026-04-15 09:00:15'),
(4,'全员异步周会预告',
'本周起，公司推行“全员异步周会”机制，目的是把“看会议”换成“看进展”，把时间还给每位伙伴。

参与方式：
- 每周五 17:00 前，在“周会助手”服务号内提交本周进展，模板为：本周成果 / 下周计划 / 需要支持的事项；
- 每周一上午 11:00 前，阅读本人所在部门的合并周报（由部门负责人审定后推送）；
- 不再安排固定时段的视频例会，确有需要的同步讨论由部门负责人临时召集即可。

模板和示例已上传到企业云盘 → 公共资源 → 周会模板。第一次提交不超过 200 字也可以，重在养成节奏，不必追求格式漂亮。',
0,1,'平台运营',0,0,0,NULL,'2026-05-18 10:50:50',1,'2026-04-24 14:59:50'),
(5,'明远科技：年中考核安排',
'各部门同仁：

2026 年上半年绩效考核将于 6 月 10 日启动，预计 6 月 28 日完成全部评审。整体节奏如下：

1. 自评阶段（6 月 10 日 - 6 月 14 日）
   登录管理后台 → 我的考核 → 上半年自评，按 OKR 完成情况勾选，并补充关键事件描述（不少于 200 字）。

2. 互评阶段（6 月 15 日 - 6 月 19 日）
   系统会自动匹配 3 - 5 名近半年协作密切的同事进行互评，互评结果对被评者匿名。

3. 直接上级评（6 月 20 日 - 6 月 24 日）
   部门负责人结合自评、互评和日常观察给出最终评级（S/A/B/C 四档）。

4. 校准会议（6 月 25 日 - 6 月 28 日）
   各中心负责人统一拉齐评级分布，结果将于 7 月 5 日发薪日同步生效。

如对评级有异议，请在结果公布后 5 个工作日内通过“HR 小助手”服务号提交申诉。',
0,1,'平台运营',1,0,0,NULL,'2026-05-14 14:59:49',1,'2026-05-14 09:41:05'),
(6,'青鸟物流：仓储系统升级',
'各仓储同事：

仓储管理系统（WMS）v3.0 将于 6 月 1 日（周一）正式切换。本次升级以“扫码即录入”为目标，预计可把入库环节人均处理时长从 8 分钟降到 3 分钟。

切换窗口：
- 5 月 31 日（周日）20:00 - 24:00：所有仓库的入出库操作暂停 4 小时；
- 切换完成后，请通过 PDA 扫描登录页二维码下载新版 App。

需要配合的事项：
1. 5 月 30 日前，请各仓主管把当前未结的盘点单、调拨单全部审核完结；
2. 切换当晚请安排 1 名值班人员驻库，确保切换后首批入库可以正常打单；
3. 若 PDA 扫描异常，临时启用 5 月 28 日下发的纸质单据流程，事后由 IT 补录。

技术支持：仓储 IT 王工 13800000003（24h 在线），切换期间专线响应。',
1,1,'平台运营',1,0,0,NULL,'2026-04-22 19:24:26',1,'2026-05-15 20:17:38'),
(7,'研发部专项通知',
'研发部同事：

下周（5 月 26 日 - 5 月 30 日）开始 v4.3 版本的开发冻结准备，请注意以下纪律：

代码冻结时间表
- 5 月 28 日 18:00：所有功能分支必须合入 release-4.3 分支；
- 5 月 29 日 全天：只允许合入 bug 修复，新功能 PR 一律转入 v4.4；
- 5 月 30 日 18:00：分支冻结，进入回归测试阶段。

发版纪律
- 任何热修复必须经过研发部负责人 + QA 双签字才能合入 release 分支；
- release 分支上的 commit message 强制按 conventional commits 格式提交，便于自动生成 changelog；
- 任何 P0 issue 在发现后 30 分钟内必须升级到部门群。

5 月 26 日 14:00 在 5 楼会议室有一次冻结前对齐会，所有 owner 必须到场或委托代表。',
0,1,'平台运营',2,0,0,NULL,'2026-05-07 17:37:21',1,'2026-05-02 10:41:31'),
(8,'平台运营内部周报',
'本周（5.13 - 5.19）平台运营周报：

核心指标
- DAU：1,254（环比 +3.2%）
- 消息发送量：83.4 万条（环比 +5.7%）
- 新增企业入驻申请：4 家（其中 2 家已签约）
- 服务工单：32 张，平均响应时长 1.8 小时

本周重点完成
- 推送 v4.2 灰度版本，覆盖 5 家先行客户；
- 完成 Q2 大客户走访 3 次，反馈整理已同步到企业云盘；
- 完善了《管理员手册 v2》，新增组织架构编辑章节。

下周计划
- 配合研发完成 v4.2 全量推送；
- 启动 2026 年下半年路线规划征集；
- 跟进 3 个续约客户的合同流程。

风险事项
- 客户“恒通物流”反馈大群体（1000+ 人）消息有延迟，待研发本周排查根因。',
0,1,'平台运营',4,0,0,NULL,'2026-04-28 16:55:38',1,'2026-04-29 20:24:03'),
(9,'端午节放假安排（草稿）',
'各位伙伴：

根据国务院办公厅通知，结合公司实际情况，端午节放假安排如下（草稿，待审批后再正式发布）：

- 放假日期：2026 年 6 月 19 日（周五）至 6 月 21 日（周日），共 3 天；
- 不需要调休；
- 6 月 22 日（周一）正常上班。

值班安排：
- IT 支持：每天 09:00 - 18:00 安排 1 人远程值班，节后再补休；
- 客服热线：维持 24 小时排班，详见客服部内部排班表；
- 其它岗位按需自行协调，请提前向部门负责人报备。

温馨提示：节前最后一周（6 月 16 日 - 6 月 18 日）将进入出行高峰，建议尽早安排车票；返程时请关注当地疫情防控要求。

预祝大家端午安康！',
0,1,'平台运营',0,0,0,NULL,NULL,0,'2026-05-02 14:47:20'),
(10,'新企业入驻欢迎',
'欢迎您加入 FlamingoIM！

为了帮助您快速完成首期接入，我们准备了一份“30 分钟上手指南”，建议按以下顺序操作：

第一步：完善企业信息（5 分钟）
登录管理后台 → 企业设置，补全 LOGO、行业、联系方式等信息，员工在客户端上会看到这些。

第二步：导入组织架构（10 分钟）
管理后台 → 组织架构 → 批量导入，下载模板填好后上传。系统会自动建好部门树并发送账号开通短信给每位员工。

第三步：发布欢迎公告（5 分钟）
管理后台 → 公告 → 新建，把贵公司的欢迎信发到全员，让大家知道平台已经就绪。

第四步：让员工登录客户端（10 分钟）
员工收到短信后下载 PC 客户端（地址在短信中），用手机号 + 验证码即可登录，首次登录需要设置 6 位以上的登录密码。

如遇任何问题，可以随时联系您的专属客户经理，或在管理后台右下角的“IT 支持”服务号留言，工作日 4 小时内回复。',
0,1,'平台运营',4,0,0,NULL,'2026-04-21 14:46:39',1,'2026-05-04 19:06:57'),
(11,'【紧急】v4.1.2 客户端强制升级公告',
'【紧急】v4.1.2 客户端存在已被证实的远程崩溃漏洞，攻击者可以通过精心构造的 emoji 让客户端崩溃并丢失本地缓存（CVE-2026-1107）。

立即行动：
1. 所有还在使用 v4.1.x 客户端的伙伴，请在 24 小时内升级到 v4.2.0；
2. 升级方式：客户端启动后会自动弹出强制更新对话框，点击“立即更新”即可，整个过程约 2 分钟；
3. 升级后旧版本将无法登录，已登录的旧版本会话也会在 24 小时后被服务端强制下线。

风险等级：高 / 影响范围：所有 v4.1.x Windows 客户端 / 修复版本：v4.2.0 及以上。

如发现客户端无法自动更新，请立即联系“IT 支持”服务号；如已经遭遇崩溃且本地缓存丢失，请通过“恢复历史消息”功能从服务端拉取（最多可恢复 90 天）。',
2,1,'平台运营',0,1,0,NULL,'2026-05-19 10:00:00',1,'2026-05-19 09:55:00'),
(12,'信息安全月活动启动',
'各位伙伴：

5 月是公司年度“信息安全月”。今年的主题是“每个人都是安全的第一道防线”，我们准备了以下系列活动，欢迎全员参与：

▍ 安全知识周课
每周二 14:00 - 14:30 在企业云盘“安全月专区”上传 1 节 30 分钟微课，本月主题安排如下：
- 第 1 周：常见社工攻击与识别方法
- 第 2 周：密码管理与多因子认证
- 第 3 周：移动办公场景下的数据防护
- 第 4 周：开发安全与代码审计入门

▍ 钓鱼演练（5 月 18 日 - 5 月 22 日）
本周内会随机向全员发送 2 - 3 封模拟钓鱼邮件，识别并上报者可获得“安全卫士”积分（兑奖列表见后文）；点击者将自动加入下周的专项培训。

▍ 安全征文比赛（5 月 1 日 - 5 月 31 日）
分享你在工作或生活中识破安全风险的真实案例，2000 字以内，一等奖 2000 元、二等奖 1000 元、三等奖 500 元，投稿邮箱：security@mingyuan-tech.com。

▍ 安全卫士积分
本月所有上报、答题、参与活动均可累积积分，月末按排名兑换礼品（米家小台灯、Kindle、JBL 音箱、出游券各 5 - 10 份）。

让我们一起把安全融入日常每一个动作。',
0,1,'平台运营',0,0,0,NULL,'2026-05-01 09:00:00',1,'2026-05-01 08:50:00'),
(13,'7月HR政策调整说明（明远人事行政部）',
'人事行政部同事：

经管理层评审通过，自 2026 年 7 月 1 日起，公司部分 HR 政策将做以下调整，请大家提前做好制度衔接：

1. 试用期评估流程优化
   - 试用期由现行的“6 个月”统一调整为“3 个月 + 必要时延长 3 个月”，由直接上级评估决定；
   - 评估表单 v2 已上传，需在 6 月 25 日前对所有在试用期员工完成一次复评。

2. 弹性工作时间
   - 在不影响协作的前提下，允许员工在 09:00 - 10:00 区间自选打卡时间；
   - 打卡规则会在 6 月 30 日前发布至“考勤助手”服务号。

3. 体检报销额度
   - 由 800 元 / 人 / 年 提高到 1200 元 / 人 / 年；
   - 入职满 3 年的员工额外增加 800 元配偶体检额度。

请人事行政部在 6 月 20 日前完成对应 SOP 的更新，并准备一份 FAQ 用于届时员工答疑。',
1,2,'王怡然',2,0,0,NULL,'2026-05-20 14:00:00',1,'2026-05-20 13:55:00'),
(14,'IT 灾备切换演练通知',
'各位伙伴：

为了验证灾备方案的有效性，IT 部计划于 6 月 3 日（周三）14:00 - 15:00 进行一次主数据中心 → 灾备中心的切换演练。

演练范围
- 客户端登录入口、消息收发、文件传输、管理后台均会临时切换到灾备机房；
- 演练窗口内可能出现 30 秒以内的会话重连，不影响数据完整性；
- 演练结束后会回切到主机房，整个过程不需要任何用户侧操作。

需要配合的事项
1. 演练期间请勿安排重要的客户演示或发布动作；
2. 如发现任何超过 1 分钟的连续异常，请第一时间在“IT 支持”服务号反馈；
3. 演练前会再发一次提醒通知，请关注。

完整演练方案与回退预案已上传到企业云盘 → IT 资料 → 灾备演练 → 2026-06。',
1,1,'平台运营',0,0,1,'2026-06-02 10:00:00',NULL,0,'2026-05-25 11:00:00'),
(15,'DevOps 月度公开课邀请（明远 + 青鸟）',
'诚邀明远科技、青鸟物流的全体伙伴一起参加 6 月的“DevOps 月度公开课”！

本期主题：从看板到指标 —— 中小团队如何落地工程效能
