2. 从 Jira 看板到流动指标的端到端实践（60 分钟）
3. 度量结果如何被团队接受 —— 文化与流程并重（45 分钟）
4. 现场互动答疑（30 分钟）

报名方式
- 线上参加：直接在本公告下方点击“我要报名”，会议链接将在开始前 1 天通过私信发送；
- 线下参加：因场地座位有限（约 40 人），请于 6 月 3 日前通过“HR 小助手”服务号报名，先到先得。

凡完成全部课程并提交课后总结者，将获得官方“DevOps 实践认证”电子证书。',
0,1,'平台运营',1,0,0,NULL,'2026-05-22 16:00:00',1,'2026-05-22 15:55:00');

-- ===== t_announcement (16-19)：超长正文，专用于复测公告详情滚动条（受众=全部企业、已发布） =====
INSERT INTO t_announcement(f_announcement_id,f_title,f_body,f_severity,f_sender_admin_id,f_sender_name,f_audience_type,f_pinned,f_scheduled,f_scheduled_time,f_sent_time,f_status,f_create_time) VALUES
(16,'【超长正文 A】FlamingoIM 平台年度运维与安全规范汇编（完整版）',
'各位伙伴：

为统一全平台的运维操作与安全基线，现将本年度各项规范汇编如下，请各企业管理员与运维同学逐条阅读并落实到日常工作中。本文篇幅较长，建议分章节阅读。

一、账号与权限
1. 所有管理后台账号必须开启二次验证，严禁多人共用同一账号；
2. 权限遵循最小化原则，离职 / 转岗人员须在 24 小时内回收对应权限；
3. 平台超级管理员账号仅限两人持有，互为备份，所有高危操作须留痕可追溯；
4. 第三方对接账号一律使用独立服务账号，禁止借用自然人账号申请密钥。

二、数据备份与恢复
1. 核心库每日全量备份一次，每小时增量备份一次，备份文件异地保存至少保留 30 天；
2. 每季度至少进行一次完整的恢复演练，演练须覆盖从冷备到热备的全链路；
3. 任何涉及删库、清表、批量改库的操作，须经双人复核并在维护窗口内执行；
4. 备份介质的访问权限单独审批，禁止与生产库共用同一套凭据。

三、变更与发布
1. 所有生产变更必须走变更单，写明变更内容、影响范围、回退方案与验证步骤；
2. 灰度发布优先，先内部、再单企业、最后全量，每一档观察期不少于 2 小时；
3. 重大版本发布须准备回退包，并在发布前确认回退路径可用；
4. 禁止在周五下午及节假日前夜进行重大变更，除非有紧急安全修复需求。

四、监控与告警
1. 关键服务的可用性、时延、错误率必须配置告警，告警须能直达值班人手机；
2. 告警分级处理：P0 五分钟内响应，P1 三十分钟内响应，P2 当个工作日内处理；
3. 误报告警须及时调整阈值，连续误报三次以上的规则须复盘；
4. 每月输出一份监控覆盖率报告，确保新上线服务全部纳入监控。

五、安全基线
1. 所有对外端口须最小化开放，非必要端口一律关闭；
2. 依赖库每月扫描一次已知漏洞，高危漏洞须在 7 个工作日内修复；
3. 日志中严禁打印明文密码、令牌、身份证号等敏感信息；
4. 安全事件须在发现后 1 小时内上报安全团队，并按预案处置。

如对以上任何条款有疑问，请通过“帮助 → 反馈问题”联系平台运营组，我们会安排专人解答。本规范自发布之日起执行，后续如有调整将另行通知。

—— 平台运营组 / 安全团队 联合发布',
0,1,'平台运营',1,0,0,NULL,'2026-05-20 10:00:00',1,'2026-05-20 09:55:00'),
(17,'【超长正文 B】客户端 v4.3 灰度升级操作手册与常见问题',
'各位企业管理员：

FlamingoIM 客户端 v4.3 将于近期分批灰度，为保证升级顺利，特整理本操作手册与常见问题，请务必转达本企业内的 IT 支持同事。

第一部分：升级前准备
1. 确认本企业内客户端当前版本不低于 v4.1，低于该版本的需先升级到 v4.1 再升 v4.3；
2. 通知员工在升级窗口前保存好正在编辑的草稿与未发送的文件；
3. 检查终端磁盘剩余空间不低于 500MB，安装包加增量数据约占用 300MB；
4. 关闭与客户端冲突的第三方注入类工具（部分截屏 / 录屏增强工具会导致界面异常）。

第二部分：升级步骤
1. 客户端在后台静默下载增量包，下载完成后会在右下角提示“可更新”；
2. 员工点击提示后客户端自动重启并完成更新，整个过程约 30 至 60 秒；
3. 若静默下载失败，可在“设置 → 关于 → 检查更新”手动触发；
4. 企业可在管理后台设置统一的升级截止时间，到期未升级的终端将被引导强制升级。

第三部分：升级后验证
1. 登录后检查联系人面板能否正常展开多级部门；
2. 发送一条文本消息与一个小文件，确认收发正常；
3. 进入任意群组，确认历史消息可正常加载；
4. 如发现异常，先尝试退出重登，仍异常再上传日志。

第四部分：常见问题
问：升级后提示“协议版本不一致”怎么办？
答：通常是服务端尚未完成灰度，等待 1 小时后重试即可，期间不影响旧版收发。

问：升级后字体显示异常 / 界面错位？
答：多为缩放设置缓存导致，在“设置 → 通用 → 重置界面缩放”后重启客户端。

问：能否回退到 v4.2？
答：可以。在登录界面长按版本号 5 秒进入回退入口，回退后请暂缓再次升级并反馈问题。

问：弱网环境下升级很慢？
答：增量包支持断点续传，保持网络连接即可，必要时切换到更稳定的网络重试。

如仍无法解决，请联系平台运营组并附上客户端日志（设置 → 帮助 → 导出日志）。感谢各位的配合！

—— 平台运营组',
1,1,'平台运营',0,0,0,NULL,'2026-05-23 11:00:00',1,'2026-05-23 10:55:00'),
(18,'【超长正文 C】关于近期钓鱼攻击激增的安全警告与全员处置指引',
'全体同事请注意：

近一周平台监测到针对企业员工的钓鱼攻击明显增多，攻击者伪装成“系统通知”“IT 支持”“财务对账”等身份，诱导员工点击伪造链接并输入账号口令。已有个别企业出现账号失陷情况，现发布本安全警告，请全员严格执行以下处置指引。

一、典型攻击手法
1. 冒充系统服务号发送“密码即将过期，请立即重置”的链接；
2. 以“待签收文件 / 待审批单据”为名诱导下载带宏的文档；
3. 假冒同事或上级，通过私聊发送“紧急转账 / 紧急授权”请求；
4. 利用短链接（t.cn、bit.ly 等）隐藏真实钓鱼域名。

二、识别要点
1. 官方系统通知服务号头像为铃铛图标，名称右侧带平台认证标识；
2. 任何要求输入“当前密码 + 新密码”的页面，域名必须以 mingyuan-tech.com 结尾；
3. 官方通知从不通过短链接跳转，均为完整域名直链；
4. 涉及资金、授权的请求，务必通过电话或当面二次确认，不轻信单一渠道。

三、若已中招的处置顺序
1. 立即在其它可信设备上修改账号口令，并退出全部已登录会话；
2. 通知本企业管理员冻结相关账号，排查最近的异常登录与操作；
3. 保留钓鱼链接、聊天记录等证据，提交安全团队分析；
4. 如涉及资金，第一时间联系财务与银行止付，并报备安全团队。

四、企业管理员应采取的措施
1. 开启全员二次验证，强制弱口令账号改密；
2. 在管理后台核查近 7 天的登录地与设备指纹，对异常项告警；
3. 组织一次面向全员的反钓鱼提醒，必要时进行一次内部钓鱼演练；
4. 收紧外部消息提醒策略，对疑似伪造的服务号进行拦截上报。

安全无小事，请大家提高警惕、互相提醒。任何疑问或发现可疑情况，请立即联系安全团队（安全热线见内网首页）。

—— 安全团队',
2,1,'安全团队',1,0,0,NULL,'2026-05-26 09:00:00',1,'2026-05-26 08:55:00'),
(19,'【超长正文 D】平台季度复盘、稳定性建设与下季度规划（特长，用于压力测试滚动）',
'各位伙伴：

本文汇总本季度的平台运行情况、稳定性建设进展与下一季度的工作规划，内容较多，特此整理，便于各团队对齐目标。请耐心读完，并就与本团队相关的部分给出反馈。

第一章 本季度总体情况
1. 平台整体可用性达到 99.95%，较上季度提升 0.07 个百分点；
2. 消息收发平均时延下降 18%，文件传输成功率提升至 99.2%；
3. 全季度共处理线上事件 42 起，其中 P0 事件 1 起、P1 事件 6 起，其余为 P2；
4. 用户活跃稳步增长，月活较上季度增长 12%。

第二章 稳定性建设进展
1. 完成核心库的读写分离改造，读流量下沉到只读副本，主库压力下降约 35%；
2. 引入连接池治理，连接泄漏类问题环比下降 80%；
3. 全链路压测常态化，每两周一次，已覆盖登录、收发、文件、组织架构四条主链路；
4. 灰度发布平台上线，支持按企业、按比例、按地域多维灰度，回退时间从分钟级降到秒级；
5. 监控覆盖率从 76% 提升到 94%，新增服务接入监控的平均时间从 3 天缩短到当天。

第三章 本季度典型事件复盘
1. 5 月某日的一次登录抖动，根因是某依赖证书过期叠加重试风暴，已补充证书到期自动告警与重试退避；
2. 文件服务一次内存增长，根因是大文件分片未及时释放，已修复并补充内存水位告警；
3. 一次组织架构展示为空，根因是缓存未在批量改库后刷新，已建立写操作后强制刷新机制。

第四章 下季度规划
1. 推进多活架构第一阶段，先实现同城双机房读多活；
2. 消息存储分层，冷热数据分离，降低热库体积与查询时延；
3. 客户端弱网体验专项，目标弱网下消息到达率再提升 5 个百分点；
4. 安全合规专项，完成一次外部渗透测试并闭环全部高危项；
5. 可观测性升级，统一日志、指标、链路追踪三件套，缩短故障定位时间。

第五章 需要各团队配合的事项
1. 各业务团队梳理本团队的核心链路并补齐监控与告警；
2. 各企业管理员配合完成一次组织架构数据校对；
3. 运维团队牵头制定多活演练计划，业务团队配合参与；
4. 安全团队牵头渗透测试，各团队按整改清单限期闭环。

以上即本季度复盘与下季度规划的全部内容。如对目标、排期或资源有不同意见，请在本周五前反馈到平台运营组，我们将汇总后统一对齐。感谢大家一个季度以来的努力与配合，让我们继续把平台做得更稳、更快、更安全。

—— 平台运营组',
0,1,'平台运营',0,0,0,NULL,'2026-05-30 18:00:00',1,'2026-05-30 17:55:00');

